/**
 * Shape of the page content files in src/content/pages/*.json
 * (generated by scripts/migration/extract_pages.py from the original site).
 */
export type ContainerNode = {
  type: "container";
  /** Elementor element id, e.g. "698c117c" — the page CSS targets it. */
  id: string;
  /** Original class list (layout: e-con-boxed / e-con-full, etc.). */
  classes: string;
  /** Elementor "CSS ID" (id attribute): target of in-page anchor links and custom CSS. */
  cssId?: string;
  animation?: string;
  children: ElementorNode[];
};

export type WidgetNode = {
  /** Elementor widget type, e.g. "heading", "text-editor", "image", "nested-tabs". */
  type: string;
  id: string;
  classes: string;
  cssId?: string;
  animation?: string;
  /** true when the content sits inside <div class="elementor-widget-container">. */
  wrapped: boolean;
  /** The widget's HTML (cleaned: local image paths, relative links, no scripts). */
  html: string;
};

export type ElementorNode = ContainerNode | WidgetNode;

export type PageContent = {
  path: string;
  /** Id of the original Elementor page (its CSS file is post-<id>.css). */
  elementorId: string;
  content: ElementorNode[];
};
